function startServer() {
  const server = http__namespace.createServer(async (req, res) => {
    const url = req.url?.split("?")[0] ?? "/";
    const method = (req.method ?? "GET").toUpperCase();
    const matched = routes.find((r2) => r2.method === method && r2.path === url);
    if (!matched) {
      jsonResponse(res, 404, { error: "Not found" });
      return;
    }
    try {
      const body = await readBody(req);
      await matched.handler(req, res, body);
    } catch (err) {
      console.error("[server] unhandled error:", err);
      jsonResponse(res, 500, { error: "Internal server error" });
    }
  });
  server.listen(PORT, "0.0.0.0", () => {
    console.log(`[server] HTTP server listening on 0.0.0.0:${PORT}`);
  });
  server.on("error", (err) => {
    console.error("[server] server error:", err);
  });
}
